import { createHash } from "node:crypto";
import { readFile, writeFile } from "node:fs/promises";
import { join, resolve } from "node:path";
import { PROJECT_REQUEST_FIELDS, verifyProjectSchemas } from "../src/codex-project-schema.js";

// Only reads a schema bundle generated by the installed Codex CLI. No RPCs or credentials.
const directory = process.argv[2];
if (!directory) throw new Error("Usage: tsx scripts/verify-codex-project-schema.ts <generated-schema-directory>");
const names = [...Object.keys(PROJECT_REQUEST_FIELDS), "v1/InitializeResponse", "v2/ProjectCreateResponse",
  "v2/ProjectReadResponse", "v2/ProjectListResponse", "v2/ThreadReadResponse"];
const documents: Record<string, unknown> = {};
const hashes: Record<string, string> = {};
for (const name of names) {
  const raw = await readFile(join(resolve(directory), `${name}.json`));
  hashes[name] = createHash("sha256").update(raw).digest("hex");
  documents[name] = JSON.parse(raw.toString("utf8"));
}
const result = { status: "passed", ...verifyProjectSchemas(documents), hashes,
  scope: "adapter request probes and selected response fields; not complete schema compatibility or live acceptance evidence" };
await writeFile(join(resolve(directory), "devspace-project-compatibility.json"), JSON.stringify(result, null, 2) + "\n");
console.log(JSON.stringify(result, null, 2));
